// ELEMENTS:
// 1. Navy liso com o filete vermelho no topo
// 2. Título (title) em Light com traço vermelho
// 3. Linhas "Rótulo: valor": filete branco a crescer, visto que se desenha, rótulo em névoa e valor em Light
//    (times = segundos desde o início da cena em que cada linha entra, para acompanhar a voz)
// 4. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const RED = "#DE212B";
const WHITE = "#FFFFFF";
const MIST = "#C9D3E3";
const LINE = "rgba(255,255,255,0.45)";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.28) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.08, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const CriteriosCheck: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const title = String(p.title ?? anim.text ?? "").trim();
  const raw = Array.isArray(p.items) ? (p.items as unknown[]).map(String) : String(anim.text ?? "").split("|");
  const items = raw.map((s) => s.trim()).filter(Boolean).map((s) => {
    const i = s.indexOf(":");
    return i > 0 ? { label: s.slice(0, i).trim(), value: s.slice(i + 1).trim() } : { label: "", value: s };
  });
  const times = Array.isArray(p.times) ? (p.times as unknown[]).map(Number) : [];

  const show = (delay: number, len = 0.7): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });

  return (
    <AbsoluteFill style={{ backgroundColor: NAVY, overflow: "hidden" }}>
      <AbsoluteFill style={{ justifyContent: "center", padding: `0 ${90 * u}px`, gap: 54 * u }}>
        <div style={{ display: "flex", flexDirection: "column", gap: 26 * u, opacity: show(0.1), transform: `translateY(${(1 - show(0.1)) * 26 * u}px)` }}>
          <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 96 * u, lineHeight: 1.05, color: WHITE }}>{title}</div>
          <div style={{ width: show(0.4, 0.7) * 110 * u, height: 3 * u, background: RED }} />
        </div>
        <div style={{ display: "flex", flexDirection: "column" }}>
          {items.map((it, i) => {
            const at = Number.isFinite(times[i]) ? times[i] : 0.6 + i * 0.55;
            const t = show(at, 0.7);
            const check = show(at + 0.25, 0.6);
            return (
              <div key={i} style={{ position: "relative", padding: `${34 * u}px 0`, display: "flex", alignItems: "center", gap: 34 * u, opacity: t, transform: `translateY(${(1 - t) * 24 * u}px)` }}>
                <div style={{ position: "absolute", top: 0, left: 0, height: 1.5 * u, width: `${t * 100}%`, background: LINE }} />
                <svg width={70 * u} height={70 * u} viewBox="0 0 70 70" style={{ flexShrink: 0 }}>
                  <circle cx={35} cy={35} r={32} fill="none" stroke={LINE} strokeWidth={2} pathLength={1} strokeDasharray={1} strokeDashoffset={1 - check} />
                  <path d="M21 36 L31 46 L50 25" fill="none" stroke={WHITE} strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - show(at + 0.55, 0.5)} />
                </svg>
                <div style={{ display: "flex", flexDirection: "column", gap: 8 * u }}>
                  {it.label ? <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 28 * u, letterSpacing: "0.32em", textTransform: "uppercase", color: MIST }}>{it.label}</div> : null}
                  <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 66 * u, lineHeight: 1.1, color: WHITE, fontVariantNumeric: "lining-nums" }}>{it.value}</div>
                </div>
              </div>
            );
          })}
          {items.length ? <div style={{ height: 1.5 * u, width: `${show(times.length ? Math.max(...times.filter(Number.isFinite)) : 0.6 + (items.length - 1) * 0.55, 0.7) * 100}%`, background: LINE }} /> : null}
        </div>
      </AbsoluteFill>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: RED }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default CriteriosCheck;
